/// Configuration for a named workflow
#[derive(Debug, Clone, Default, Serialize, Deserialize, JsonSchema)]
#[serde(default, deny_unknown_fields)]
pub struct WorkflowConfig {
    /// Human-readable description
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,

    /// Ordered list of step names to execute
    #[serde(default)]
    pub steps: Vec<String>,

    /// Step-specific overrides for this workflow
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub overrides: HashMap<String, StepOverride>,

    /// Workflow-level settings
    #[serde(skip_serializing_if = "Option::is_none")]
    pub settings: Option<WorkflowSettings>,

    /// Override auto_run for all steps in this workflow.
    /// Individual step overrides take precedence.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub auto_run_steps: Option<bool>,

    /// Workflow-level environment variables
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub env: HashMap<String, String>,

    /// Workflow-level env file
    #[serde(skip_serializing_if = "Option::is_none")]
    pub env_file: Option<PathBuf>,

    /// Steps to always force when this workflow runs. Same effect as
    /// passing `--force <step>` on the CLI for each entry. Step names
    /// must reference steps defined in the configuration.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub force: Vec<String>,

    /// Force every step in this workflow, bypassing all checks and
    /// step-level configuration. Equivalent to passing `--force-all`
    /// every time this workflow runs.
    #[serde(default, skip_serializing_if = "is_false")]
    pub force_all: bool,
}

/// A self-contained workflow file. Lives at `.bivvy/workflows/<stem>.yml`.
///
/// Can carry its own step definitions, vars, and workflow declaration.
/// When loaded as part of `bivvy run <stem>`, the contents are spliced
/// into the merged [`BivvyConfig`] at the workflow-file slot of the
/// resolution chain (between split steps and `config.local.yml`).
#[derive(Debug, Clone, Default, Serialize, Deserialize, JsonSchema)]
#[serde(default, deny_unknown_fields)]
pub struct WorkflowFile {
    /// Human-readable description (shown in `bivvy list`).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,

    /// Step definitions private to this workflow file (in the absence of
    /// overrides from later in the resolution chain).
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub steps: HashMap<String, StepConfig>,

    /// Variables available during interpolation when this workflow runs.
    /// Merged into the global vars table from `.bivvy/config.yml`.
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub vars: HashMap<String, VarDefinition>,

    /// The workflow declaration itself: ordering, env, force directives.
    #[serde(default)]
    pub workflow: WorkflowConfig,
}

/// Per-step overrides within a workflow
#[derive(Debug, Clone, Default, Serialize, Deserialize, JsonSchema)]
#[serde(default, deny_unknown_fields)]
pub struct StepOverride {
    /// Skip prompts, just run
    #[serde(default, skip_serializing_if = "is_false")]
    pub skip_prompt: bool,

    /// Override required flag
    #[serde(skip_serializing_if = "Option::is_none")]
    pub required: Option<bool>,

    /// Override auto_run flag.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub auto_run: Option<bool>,

    /// Override prompt_on_rerun flag.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub prompt_on_rerun: Option<bool>,

    /// Override rerun_window.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub rerun_window: Option<String>,
}

/// Workflow-level settings overrides
#[derive(Debug, Clone, Default, Serialize, Deserialize, JsonSchema)]
#[serde(default, deny_unknown_fields)]
pub struct WorkflowSettings {
    /// Force non-interactive mode for this workflow
    #[serde(default, skip_serializing_if = "is_false")]
    pub non_interactive: bool,
}

/// Source kind for a remote template registry.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum TemplateSourceKind {
    /// Fetch a single YAML file (or list of templates) over HTTP/HTTPS.
    Http,
    /// Clone a git repository and walk its templates directory.
    Git,
}

/// Remote template source configuration
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct TemplateSource {
    /// Source kind. When omitted, auto-detected from `url`:
    /// SCP-style (`git@...`), `ssh://`, `git://`, or URLs ending in `.git`
    /// are treated as `git`; everything else as `http`.
    #[serde(rename = "type", default, skip_serializing_if = "Option::is_none")]
    pub kind: Option<TemplateSourceKind>,

    /// URL to template repository or file
    pub url: String,

    /// Git ref (branch, tag, or commit SHA). Only used for git sources.
    #[serde(rename = "ref", default, skip_serializing_if = "Option::is_none")]
    pub git_ref: Option<String>,

    /// Subdirectory within the git repository to walk for `*.yml` templates.
    /// Defaults to the repository root when omitted. Only used for git sources.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub path: Option<String>,

    /// Priority (lower = higher priority)
    #[serde(default = "default_priority")]
    pub priority: u32,

    /// Network timeout in seconds
    #[serde(default = "default_timeout")]
    pub timeout: u64,

    /// Cache configuration
    pub cache: Option<CacheConfig>,

    /// Authentication configuration
    pub auth: Option<AuthConfig>,
}

impl TemplateSource {
    /// Resolve the effective source kind, auto-detecting from `url` when
    /// `kind` is not explicitly set.
    pub fn effective_kind(&self) -> TemplateSourceKind {
        if let Some(k) = self.kind {
            return k;
        }
        detect_kind_from_url(&self.url)
    }
}

/// Auto-detect the source kind from a URL.
///
/// Returns `Git` for SCP-style addresses (`git@host:path`), `ssh://`, `git://`,
/// or URLs ending in `.git`. Everything else is `Http`.
pub fn detect_kind_from_url(url: &str) -> TemplateSourceKind {
    if url.starts_with("git@") || url.starts_with("ssh://") || url.starts_with("git://") {
        return TemplateSourceKind::Git;
    }

    let trimmed = url.trim_end_matches('/');
    if trimmed.ends_with(".git") {
        return TemplateSourceKind::Git;
    }

    TemplateSourceKind::Http
}

fn default_priority() -> u32 {
    100
}

fn default_timeout() -> u64 {
    30
}

