    fn empty_local_override_does_not_wipe_project_config() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();

        fs::write(
            bivvy_dir.join("config.yml"),
            r#"
app_name: MyApp
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#,
        )
        .unwrap();

        // Empty local override (parses to null)
        fs::write(bivvy_dir.join("config.local.yml"), "").unwrap();

        let config = load_merged_config(temp.path()).unwrap();
        assert_eq!(config.app_name, Some("MyApp".to_string()));
        assert!(config.steps.contains_key("hello"));
