    }

    #[test]
    fn comments_only_local_override_does_not_wipe_project_config() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();

        fs::write(
            bivvy_dir.join("config.yml"),
            r#"
app_name: Preserved
steps:
  build:
    command: cargo build
"#,
        )
        .unwrap();

        // Local override with only comments
        fs::write(
